/* Begin auto-generated constants. */

static const float tiny = 1.0e-30f;
static const float half = 0.5f;
static const float one = 1.0f;
static const float two = 2.0f;

// 0x3f57bb00
static const float erx = 8.42697144e-01f;

// Polynomial coefficients for domain [0, 0.84375]:
static const float pp0 = 1.28379166e-01f;  // 0x3e0375d4
static const float pp1 = -3.36030394e-01f; // 0xbeac0c2d
static const float pp2 = -1.86261395e-03f; // 0xbaf422f4
