static const float qq2 = 2.16070414e-02f;  // 0x3cb10140
static const float qq3 = -1.98859372e-03f; // 0xbb025311

// Polynomial coefficients for domain [0.84375, 1.25]:
static const float pa0 = 3.65041046e-06f;  // 0x3674f993
static const float pa1 = 4.15109307e-01f;  // 0x3ed48935
static const float pa2 = -2.09395722e-01f; // 0xbe566bd5
static const float pa3 = 8.67677554e-02f;  // 0x3db1b34b
static const float qa1 = 4.95560974e-01f;  // 0x3efdba2b
static const float qa2 = 3.71248513e-01f;  // 0x3ebe1449
static const float qa3 = 3.92478965e-02f;  // 0x3d20c267

// Polynomial coefficients for domain [1.25, 1/0.35]:
static const float ra0 = -9.88156721e-03f; // 0xbc21e64c
static const float ra1 = -5.43658376e-01f; // 0xbf0b2d32
static const float ra2 = -1.66828310e+00f; // 0xbfd58a4d
static const float ra3 = -6.91554189e-01f; // 0xbf3109b2
static const float sa1 = 4.48581553e+00f;  // 0x408f8bcd
static const float sa2 = 4.10799170e+00f;  // 0x408374ab
static const float sa3 = 5.53855181e-01f;  // 0x3f0dc974

// Polynomial coefficients for domain [2.85715, 11]:
static const float rb0 = -9.86496918e-03f; // 0xbc21a0ae
static const float rb1 = -5.48049808e-01f; // 0xbf0c4cfe
static const float rb2 = -1.84115684e+00f; // 0xbfebab07
static const float sb1 = 4.87132740e+00f;  // 0x409be1ea
static const float sb2 = 3.04982710e+00f;  // 0x4043305e
static const float sb3 = -7.61900663e-01f; // 0xbf430bec

/* End auto-generated constants. */

/**
* Evaluates the complementary error function for a single-precision floating-point number.
*
* ## Method
*
* 1.  For \\( x \in [0, 0.84375] \\), we use the approximation
*
*     ```tex
*     \operatorname{erfc}(x) = 1 - \operatorname{erf}(x) = 1 - x \cdot \frac{P(x^2)}{Q(x^2)}
*     ```
*
*     where \\( P \\) and \\( Q \\) are polynomials (pp and qq).
*
* 2.  For \\( x \in [0.84375, 1.25] \\), we use the approximation
*
*     ```tex
*     \operatorname{erfc}(x) = 1 - \operatorname{erf}(x) = 1 - \operatorname{erx} - \frac{P(x-1)}{Q(x-1)}
*     ```
*
*     where \\( P \\) and \\( Q \\) are polynomials (pa and qa).
*
* 3.  For \\( x \in [1.25, 11] \\), we use the approximation
*
*     ```tex
*     \operatorname{erfc}(x) = \frac{1}{x} e^{-x^2 - 0.5625 + \frac{R(1/x^2)}{S(1/x^2)}}
*     ```
*
*     where \\( R \\) and \\( S \\) are rational functions (ra/sa for x < 2.85715, rb/sb for x >= 2.85715).
*
* 4.  For \\( x \geq 11 \\), we use the approximation
*
*     ```tex
*     \operatorname{erfc}(x) = 0
*     ```
*
* ## Notes
*
* -   Relative error:
*     - \\( |x| < 0.84375 \\): \\( 2^{-31} \\)
*     - \\( 0.84375 \leq |x| < 1.25 \\): \\( 2^{-31} \\)
*     - \\( 1.25 \leq |x| < 2.85715 \\): \\( 2^{-30} \\)
*     - \\( 2.85715 \leq |x| < 11 \\): \\( 2^{-30} \\)
*
* @param x    input value
* @return     function value
*
* @example
* float y = stdlib_base_erfcf( 0.0f );
* // returns 1.0f
*
* @example
* float y = stdlib_base_erfcf( 1.0f );
* // returns ~0.1573f
*/
float stdlib_base_erfcf( const float x ) {
    stdlib_base_float32_word_t wx;
    float R;
    float S;
    float P;
    float Q;
    float s;
    float y;
    float z;
    float r;
    int32_t hx;
    int32_t ix;

    // Handle NaN:
    if ( x != x ) {
        return x;
    }

    wx.value = x;
    hx = (int32_t)wx.word;
    ix = hx & 0x7fffffff;

    // Case: |x| < 0.84375
    if ( ix < 0x3f580000 ) {
        // Case: |x| < 2**-24
        if ( ix < 0x33800000 ) {
            return one - x;
        }
        z = x * x;
        r = pp0 + ( z * ( pp1 + ( z * pp2 ) ) );
        s = one + ( z * ( qq1 + ( z * ( qq2 + ( z * qq3 ) ) ) ) );
        y = r / s;
        if ( hx < 0x3e800000 ) {
            // Case: x < 1/4
            return one - ( x + ( x * y ) );
        }
        r = x * y;
        r += ( x - half );
        return half - r;
    }
    // Case: 0.84375 <= |x| < 1.25
    if ( ix < 0x3fa00000 ) {
        s = stdlib_base_absf( x ) - one;
        P = pa0 + ( s * ( pa1 + ( s * ( pa2 + ( s * pa3 ) ) ) ) );
        Q = one + ( s * ( qa1 + ( s * ( qa2 + ( s * qa3 ) ) ) ) );
        if ( hx >= 0 ) {
            z = one - erx;
            return z - ( P / Q );
        }
        z = erx + ( P / Q );
        return one + z;
    }
    // Case: |x| < 11
    if ( ix < 0x41300000 ) {
        float ax;
        float xm2;
        
        ax = stdlib_base_absf( x );
        s = one / ( ax * ax );
        
        // Case: |x| < 2.85715 ~ 1/0.35
        if ( ix < 0x4036db8c ) {
            R = ra0 + ( s * ( ra1 + ( s * ( ra2 + ( s * ra3 ) ) ) ) );
            S = one + ( s * ( sa1 + ( s * ( sa2 + ( s * sa3 ) ) ) ) );
        } else {
            // Case: x < -5
            if ( hx < 0 && ix >= 0x40a00000 ) {
                return two - tiny;
            }
            R = rb0 + ( s * ( rb1 + ( s * rb2 ) ) );
            S = one + ( s * ( sb1 + ( s * ( sb2 + ( s * sb3 ) ) ) ) );
        }
        wx.word = (uint32_t)( hx & 0xffffe000 );
        z = wx.value;
        xm2 = ( z - ax ) * ( z + ax );
        r = (float)stdlib_base_exp( (double)( ( -z * z ) - 0.5625 + xm2 + ( R / S ) ) );
        if ( hx > 0 ) {
            // Handle underflow for large positive x:
            if ( r < 1.0e-37f ) {
                return 0.0f;
            }
            return r / ax;
        }
        return two - ( r / ax );
    }
    // Case: |x| >= 11
    if ( hx > 0 ) {
        return 0.0f;
    }
    return 2.0f;
}